I love that idea! Let's build a classic, super addictive **"Catch the Coin"** arcade game right in your browser. 

It’s completely self-contained in a single HTML file, so all you have to do is save it and open it in any browser. You'll use your left and right arrow keys to move the basket and catch falling gold coins while avoiding bombs!

Here is the complete, production-ready code:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Catch the Coin! - Krishna Tech Unlimited</title>
    <style>
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }
        body {
            background: linear-gradient(135deg, #1e1e2f, #2a2a40);
            color: #ffffff;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            overflow: hidden;
        }
        h1 {
            margin-bottom: 10px;
            font-size: 2rem;
            text-shadow: 0 2px 4px rgba(0,0,0,0.5);
        }
        #game-container {
            position: relative;
            width: 400px;
            height: 600px;
            background: #111118;
            border: 4px solid #4e4e6a;
            border-radius: 12px;
            overflow: hidden;
            box-shadow: 0 10px 30px rgba(0,0,0,0.7);
        }
        .basket {
            position: absolute;
            bottom: 20px;
            left: 160px;
            width: 80px;
            height: 25px;
            background: #f39c12;
            border-radius: 5px 5px 15px 15px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.3);
        }
        .item {
            position: absolute;
            width: 30px;
            height: 30px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
        }
        .coin {
            background: #f1c40f;
            color: #7f6000;
            box-shadow: 0 0 10px #f1c40f;
        }
        .bomb {
            background: #e74c3c;
            color: #fff;
            box-shadow: 0 0 10px #e74c3c;
        }
        #scoreboard {
            display: flex;
            justify-content: space-between;
            width: 400px;
            margin-bottom: 10px;
            font-size: 1.2rem;
            font-weight: bold;
        }
        #game-over {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.85);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            display: none;
        }
        #game-over h2 {
            font-size: 2.5rem;
            color: #e74c3c;
            margin-bottom: 15px;
        }
        button {
            padding: 10px 20px;
            font-size: 1rem;
            background: #2ecc71;
            color: white;
            border: none;
            border-radius: 5px;
            cursor: pointer;
            transition: background 0.2s;
        }
        button:hover {
            background: #27ae60;
        }
        .instructions {
            margin-top: 10px;
            font-size: 0.9rem;
            color: #a0a0c0;
        }
    </style>
</head>
<body>

    <h1>Catch the Coin!</h1>

    <div id="scoreboard">
        <span id="score-display">Score: 0</span>
        <span id="lives-display">Lives: 3</span>
    </div>

    <div id="game-container">
        <div class="basket" id="basket"></div>
        <div id="game-over">
            <h2>Game Over</h2>
            <p id="final-score" style="margin-bottom: 20px; font-size: 1.2rem;"></p>
            <button onclick="restartGame()">Play Again</button>
        </div>
    </div>

    <div class="instructions">Use <b>Left</b> and <b>Right Arrow Keys</b> to move. Avoid bombs!</div>

    <script>
        const container = document.getElementById('game-container');
        const basket = document.getElementById('basket');
        const scoreDisplay = document.getElementById('score-display');
        const livesDisplay = document.getElementById('lives-display');
        const gameOverScreen = document.getElementById('game-over');
        const finalScoreText = document.getElementById('final-score');

        let basketX = 160;
        let score = 0;
        let lives = 3;
        let isGameOver = false;
        let items = [];
        let gameInterval, spawnerInterval;

        const keys = { ArrowLeft: false, ArrowRight: false };

        window.addEventListener('keydown', (e) => {
            if (keys.hasOwnProperty(e.key)) keys[e.key] = true;
        });

        window.addEventListener('keyup', (e) => {
            if (keys.hasOwnProperty(e.key)) keys[e.key] = false;
        });

        function spawnItem() {
            if (isGameOver) return;

            const isBomb = Math.random() < 0.25; // 25% chance for a bomb
            const itemElem = document.createElement('div');
            itemElem.classList.add('item', isBomb ? 'bomb' : 'coin');
            itemElem.innerText = isBomb ? '💣' : '🪙';

            const itemX = Math.floor(Math.random() * 370);
            itemElem.style.left = itemX + 'px';
            itemElem.style.top = '0px';

            container.appendChild(itemElem);

            items.push({
                element: itemElem,
                x: itemX,
                y: 0,
                isBomb: isBomb,
                speed: 3 + Math.random() * 3 // Random falling speed
            });
        }

        function updateGame() {
            if (isGameOver) return;

            // Move Basket
            if (keys.ArrowLeft && basketX > 0) {
                basketX -= 7;
            }
            if (keys.ArrowRight && basketX < 320) {
                basketX += 7;
            }
            basket.style.left = basketX + 'px';

            // Update Items
            for (let i = items.length - 1; i >= 0; i--) {
                let item = items[i];
                item.y += item.speed;
                item.element.style.top = item.y + 'px';

                // Check Collision with Basket
                // Basket is at bottom: 20px, height: 25px -> Y range: 555 to 580
                if (item.y >= 545 && item.y <= 580 && item.x + 30 >= basketX && item.x <= basketX + 80) {
                    if (item.isBomb) {
                        lives--;
                        if (lives <= 0) endGame();
                    } else {
                        score += 10;
                    }
                    item.element.remove();
                    items.splice(i, 1);
                    updateUI();
                } 
                // Check if item hit bottom
                else if (item.y > 600) {
                    if (!item.isBomb) {
                        lives--; // Lose a life if you miss a coin
                        if (lives <= 0) endGame();
                        updateUI();
                    }
                    item.element.remove();
                    items.splice(i, 1);
                }
            }
        }

        function updateUI() {
            scoreDisplay.innerText = `Score: ${score}`;
            livesDisplay.innerText = `Lives: ${lives}`;
        }

        function endGame() {
            isGameOver = true;
            clearInterval(gameInterval);
            clearInterval(spawnerInterval);
            finalScoreText.innerText = `Your Final Score: ${score}`;
            gameOverScreen.style.display = 'flex';
        }

        function restartGame() {
            items.forEach(item => item.element.remove());
            items = [];
            score = 0;
            lives = 3;
            basketX = 160;
            isGameOver = false;
            gameOverScreen.style.display = 'none';
            updateUI();

            gameInterval = setInterval(updateGame, 1000 / 60);
            spawnerInterval = setInterval(spawnItem, 800);
        }

        // Start Game
        gameInterval = setInterval(updateGame, 1000 / 60);
        spawnerInterval = setInterval(spawnItem, 800);
    </script>
</body>
</html>
```

### How to play:
1. Copy the code above.
2. Paste it into a text editor (like Notepad or VS Code) and save it as `game.html`.
3. Double-click the file to open it in your browser!

Have fun, and let me know if you want to add levels, power-ups, or audio effects!
